import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CdTmk4Xw.js";const k=JSON.parse('{"title":"CodeFlare · 项目文档","description":"","frontmatter":{"editLink":true},"headers":[],"relativePath":"repository.md","filePath":"repository.md"}'),i={name:"repository.md"};function d(h,e,o,l,n,c){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="codeflare-·-项目文档" tabindex="-1">CodeFlare · 项目文档 <a class="header-anchor" href="#codeflare-·-项目文档" aria-label="Permalink to &quot;CodeFlare · 项目文档&quot;">​</a></h1><p>CodeFlare 是以 C++ 为主的算法竞赛源码、模板与练习归档，按 OJ 和比赛组织。本分支 <code>docs/project-guide</code> 维护项目指南、静态题库的 API 契约与 VitePress 文档站。</p><p><a href="https://codeflare.lucius7.dev" target="_blank" rel="noreferrer">项目网站</a> · <a href="https://codeflare.lucius7.dev/docs/" target="_blank" rel="noreferrer">在线文档</a> · <a href="https://github.com/xw7qwq/codeflare" target="_blank" rel="noreferrer">源码仓库</a> · <a href="./catalog.html">目录清单</a> · <a href="./contributing.html">贡献指南</a></p><h2 id="文档导航" tabindex="-1">文档导航 <a class="header-anchor" href="#文档导航" aria-label="Permalink to &quot;文档导航&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要做什么</th><th>入口</th></tr></thead><tbody><tr><td>接入题库数据、查阅字段与错误规范</td><td><a href="./api/">API 参考</a></td></tr><tr><td>了解所有平台、模板和工具的位置</td><td><a href="./structure.html">项目结构</a>、<a href="./catalog.html">自动生成的目录清单</a></td></tr><tr><td>在本地编译一道题</td><td><a href="./quick-start.html">快速开始</a></td></tr><tr><td>添加题解、记录验证结果</td><td><a href="./conventions.html">代码与归档规范</a>、<a href="./contributing.html">贡献指南</a></td></tr><tr><td>配置编辑器和题目导入</td><td><a href="./tooling.html">开发工具</a></td></tr><tr><td>更新文档或维护网站</td><td><a href="./maintenance.html">维护流程</a>、<a href="./pages.html">GitHub Pages 维护</a></td></tr><tr><td>浏览全部文档主题</td><td><a href="./handbook.html">文档导航</a></td></tr></tbody></table><p>API 文档描述静态 JSON 快照及网站依赖的外部接口，不是在线评测服务。OpenAPI 和 JSON Schema 的下载入口位于 <a href="./api/">API 参考</a>。</p><h2 id="分支职责" tabindex="-1">分支职责 <a class="header-anchor" href="#分支职责" aria-label="Permalink to &quot;分支职责&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分支</th><th>内容</th></tr></thead><tbody><tr><td><a href="https://github.com/xw7qwq/codeflare/tree/main" target="_blank" rel="noreferrer"><code>main</code></a></td><td>算法源码、模板和已有开发工具</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/tree/docs/project-guide" target="_blank" rel="noreferrer"><code>docs/project-guide</code></a></td><td>本分支：文档源、API 契约、项目规范和构建检查</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/tree/gh-pages" target="_blank" rel="noreferrer"><code>gh-pages</code></a></td><td>题库网站、数据快照和生成的 <code>docs/</code> 文档网站</td></tr></tbody></table><p>文档无需合并到 <code>main</code>。推送本分支后，工作流构建文档并仅更新 <code>gh-pages/docs/</code>。源码清单记录所依据的主分支提交，刷新方法见<a href="./maintenance.html">维护流程</a>。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h3 id="阅读与检查-markdown" tabindex="-1">阅读与检查 Markdown <a class="header-anchor" href="#阅读与检查-markdown" aria-label="Permalink to &quot;阅读与检查 Markdown&quot;">​</a></h3><p>直接在 GitHub 或 Markdown 阅读器中浏览文档，无需运行网站。检查脚本需要 Git 和 Python 3.10+，不依赖第三方 Python 包。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/project-guide</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/xw7qwq/codeflare.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codeflare-docs</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codeflare-docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docs.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>请保留完整 Git 历史与远程分支引用，清单校验和 API 检查会读取指定提交及 <code>origin/gh-pages</code>。单题编译需要对应语言的工具链，见<a href="./quick-start.html">快速开始</a>。</p><h3 id="预览文档网站" tabindex="-1">预览文档网站 <a class="header-anchor" href="#预览文档网站" aria-label="Permalink to &quot;预览文档网站&quot;">​</a></h3><p>在仓库根目录执行，需要 Node.js 22+ 和 npm：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <a href="http://127.0.0.1:4174/docs/" target="_blank" rel="noreferrer">http://127.0.0.1:4174/docs/</a>，按 <code>Ctrl+C</code> 停止服务。</p><p>开发服务器启动时会将 Markdown 转换到 <code>site/.content/</code>。编辑源文档后，可在另一个终端运行 <code>npm --prefix site run prepare:docs</code> 重新生成页面内容。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>用途</th></tr></thead><tbody><tr><td><a href="./repository.html">README.md</a>、<a href="./contributing.html">CONTRIBUTING.md</a></td><td>项目入口与贡献约定</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/tree/docs/project-guide/docs/" target="_blank" rel="noreferrer">docs/</a></td><td>指南、API 说明与源码目录清单</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/scripts/docs.py" target="_blank" rel="noreferrer">scripts/docs.py</a></td><td>Markdown、相对链接、标题锚点和源码清单检查</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/site/package.json" target="_blank" rel="noreferrer">site/package.json</a></td><td>文档站依赖、开发与构建命令</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/tree/docs/project-guide/site/.vitepress/" target="_blank" rel="noreferrer">site/.vitepress/</a></td><td>站点配置和主题</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/tree/docs/project-guide/site/public/api/" target="_blank" rel="noreferrer">site/public/api/</a></td><td>OpenAPI 与 JSON Schema 契约</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/site/prepare.mjs" target="_blank" rel="noreferrer">site/prepare.mjs</a>、<a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/site/check-build.mjs" target="_blank" rel="noreferrer">site/check-build.mjs</a></td><td>内容转换与构建产物检查</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/site/publish.mjs" target="_blank" rel="noreferrer">site/publish.mjs</a></td><td>文档产物发布与上线验证</td></tr><tr><td><a href="https://github.com/xw7qwq/codeflare/blob/docs/project-guide/.github/workflows/docs.yml" target="_blank" rel="noreferrer">.github/workflows/docs.yml</a></td><td>文档校验、构建与发布工作流</td></tr></tbody></table><p><code>site/.content/</code>、<code>site/.vitepress/dist/</code> 和 <code>site/node_modules/</code> 是生成目录；修改 Markdown 源文件与配置，不提交生成目录。算法源码的分类与数量以<a href="./structure.html">项目结构</a>和<a href="./catalog.html">目录清单</a>为准。</p><h2 id="验证与贡献" tabindex="-1">验证与贡献 <a class="header-anchor" href="#验证与贡献" aria-label="Permalink to &quot;验证与贡献&quot;">​</a></h2><p>安装文档站依赖后，在仓库根目录运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/docs.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check:api</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> site</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><p>上述命令分别校验文档与清单、API 契约及快照、静态站点构建和空白格式。API 检查默认读取本地 <code>origin/gh-pages</code> 中的两份数据快照；这些检查不评测算法，也不证明远端网站已经部署成功。</p><p>从 <code>docs/project-guide</code> 创建文档工作分支，按路径提交修改，并在 Pull Request 中说明原因、变更与验证结果。新增 Markdown 或链接目标需先纳入 Git 跟踪。完整要求见<a href="./contributing.html">贡献指南</a>。</p><h2 id="域名与部署" tabindex="-1">域名与部署 <a class="header-anchor" href="#域名与部署" aria-label="Permalink to &quot;域名与部署&quot;">​</a></h2><p>CodeFlare 使用独立域名 <strong><a href="https://codeflare.lucius7.dev" target="_blank" rel="noreferrer">codeflare.lucius7.dev</a></strong>，文档站发布到 <a href="https://codeflare.lucius7.dev/docs/" target="_blank" rel="noreferrer">/docs/</a>，静态 API 位于 <code>/data/</code>。</p><p>GitHub Pages 的发布来源应为 <code>gh-pages</code> 分支根目录，自定义域名设置为 <code>codeflare.lucius7.dev</code>。文档发布脚本会核验目标仓库、来源分支与域名，只更新受管理的 <code>docs/</code> 目录，保留题库和域名配置。</p><p>API 集合 <code>2.0.0</code> 使用新域名与 <code>xw7qwq/codeflare</code> 仓库标识，响应字段结构保持不变。迁移和兼容范围见<a href="./api/standards.html">错误与兼容规范</a>。源码清单仍保留原提交 SHA、时间与统计口径。</p><p>工作流在 <code>docs/**</code> 分支推送或符合路径条件的 Pull Request 中运行检查；发布作业仅针对 <code>docs/project-guide</code> 的推送。以 <a href="https://github.com/xw7qwq/codeflare/actions" target="_blank" rel="noreferrer">Actions</a>、公开页面和 <code>docs/build-info.json</code> 核对发布结果，详细流程见<a href="./maintenance.html">维护文档</a>。</p><h2 id="内容与许可" tabindex="-1">内容与许可 <a class="header-anchor" href="#内容与许可" aria-label="Permalink to &quot;内容与许可&quot;">​</a></h2><p>每份算法源码独立使用，没有全仓统一可执行程序。归档包含未完成草稿和不带 <code>main</code> 的模板片段；文件存在、提交到 Git 或网页可见，都不代表已通过 OJ。原题以对应 OJ 页面为准。</p><p>仓库目前未声明统一的开源许可证。引用题面、第三方代码或依赖时，保留其来源并遵守各自许可；本文档不新增授权条款。</p><h2 id="相关项目" tabindex="-1">相关项目 <a class="header-anchor" href="#相关项目" aria-label="Permalink to &quot;相关项目&quot;">​</a></h2><p><a href="https://github.com/xw7qwq/ojflare" target="_blank" rel="noreferrer">OJFlare</a> 使用独立域名 <a href="https://ojflare.lucius7.dev" target="_blank" rel="noreferrer">ojflare.lucius7.dev</a>，与 CodeFlare 分别维护和部署。</p>`,37)])])}const g=t(i,[["render",d]]);export{k as __pageData,g as default};
